import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class BoundedQueue<T> {
    private final Object[] buffer;
    private int head;  // Index to remove from
    private int tail;  // Index to add to
    private int count; // Number of elements in queue

    private final Lock lock = new ReentrantLock();
    private final Condition notFull = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    public BoundedQueue(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        buffer = new Object[capacity];
        head = 0;
        tail = 0;
        count = 0;
    }

    public void enqueue(T item) throws InterruptedException {
        lock.lock();
        try {
            // Wait while queue is full
            while (count == buffer.length) {
                notFull.await();
            }

            buffer[tail] = item;
            tail = (tail + 1) % buffer.length;
            count++;

            // Signal waiting consumers that queue is not empty
            notEmpty.signal();
        } finally {
            lock.unlock();
        }
    }

    public T dequeue() throws InterruptedException {
        lock.lock();
        try {
            // Wait while queue is empty
            while (count == 0) {
                notEmpty.await();
            }

            @SuppressWarnings("unchecked")
            T item = (T) buffer[head];
            buffer[head] = null; // Help garbage collection
            head = (head + 1) % buffer.length;
            count--;

            // Signal waiting producers that queue is not full
            notFull.signal();

            return item;
        } finally {
            lock.unlock();
        }
    }

    public int size() {
        lock.lock();
        try {
            return count;
        } finally {
            lock.unlock();
        }
    }

    public int capacity() {
        return buffer.length;
    }
}

